package in.tutorlink.config; import in.tutorlink.entity.*; import in.tutorlink.repository.*; import org.springframework.boot.*; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.security.crypto.password.*; import java.time.*; import java.util.*;
@Configuration public class SeedData { @Bean CommandLineRunner seed(UserRepository users,TutorProfileRepository tutors,TuitionRepository tuition,PasswordEncoder encoder){return x->{if(users.count()>0)return;User admin=user(users,encoder,"TutorLink Admin","admin@tutorlink.in",Role.ADMIN,"Hyderabad");User akshay=user(users,encoder,"Akshay N","akshay@example.com",Role.STUDENT,"Hyderabad");User priya=user(users,encoder,"Priya Sharma","priya@example.com",Role.PARENT,"Kukatpally");TutorProfile ap=new TutorProfile();ap.user=akshay;ap.college="JNTU Hyderabad";ap.degree="B.Tech";ap.branch="Computer Science & Engineering";ap.studyYear="3rd Year";ap.location="Hyderabad";ap.teachingMode="Both";ap.availability="Weekdays 5 PM - 8 PM, Weekends flexible";ap.bio="Passionate CSE undergraduate with 3+ years experience mentoring school students in Mathematics, Physics and Coding.";ap.experienceYears=3;ap.monthlyFee=3500;ap.rating=4.9;ap.completedTuitions=3;ap.verificationStatus=VerificationStatus.VERIFIED;ap.subjects.addAll(Set.of("Mathematics","Physics","Computer Science"));ap.classes.addAll(Set.of("8th","9th","10th","11th","12th"));ap.languages.addAll(Set.of("English","Hindi","Telugu"));tutors.save(ap);String[] names={"Ananya Rao","Rahul Verma","Sneha Iyer","Kiran Kumar","Meera Shah","Vikram Singh","Divya Reddy","Arjun Nair","Kavya Jain","Rohan Das"};String[] locations={"Kukatpally","Madhapur","Gachibowli","Miyapur","Hitech City"};String[] subjects={"Mathematics","Science","English","Computer Science","Physics"};for(int i=0;i<names.length;i++){User u=user(users,encoder,names[i],"tutor"+i+"@example.com",Role.STUDENT,locations[i%5]);TutorProfile p=new TutorProfile();p.user=u;p.college=i%2==0?"JNTU Hyderabad":"Osmania University";p.degree="B.Tech";p.branch="Computer Science";p.studyYear=(2+i%3)+"th Year";p.location=u.location;p.teachingMode=i%3==0?"Online":"Both";p.availability="Weekday evenings";p.experienceYears=1+i%3;p.monthlyFee=2500+i*250;p.rating=4.2+(i%4)*.2;p.verificationStatus=i%2==0?VerificationStatus.VERIFIED:VerificationStatus.PENDING;p.subjects.add(subjects[i%subjects.length]);p.subjects.add("Mathematics");p.classes.addAll(Set.of("8th","9th","10th"));p.languages.addAll(Set.of("English","Hindi","Telugu"));tutors.save(p);}for(int i=0;i<12;i++){TuitionRequirement r=new TuitionRequirement();r.parent=priya;r.studentClass=(6+i%5)+"th";r.location=locations[i%5];r.teachingMode=i%2==0?"Offline":"Both";r.days="Monday, Wednesday, Friday";r.preferredTime="5 PM – 7 PM";r.budget=2500+i*250;r.classesPerWeek=3;r.startDate=LocalDate.now().plusDays(7);r.additionalRequirements="Looking for a patient college tutor.";r.subjects.add(subjects[i%subjects.length]);r.subjects.add("Mathematics");tuition.save(r);}};} private User user(UserRepository r,PasswordEncoder e,String name,String email,Role role,String location){User u=new User();u.fullName=name;u.email=email;u.password=e.encode("Password@123");u.role=role;u.location=location;return r.save(u);}}
